from textkit.pairs import parse_pairs, ParseError
import pytest
# Repro from task
try:
    parse_pairs('a=1;oops')
except ParseError as e:
    print('oops ->', repr(str(e)))
except Exception as e:
    print('oops -> WRONG', type(e).__name__, repr(e))
try:
    parse_pairs('=1')
except ParseError as e:
    print('=1 ->', repr(str(e)))
else:
    print('=1 -> WRONG', parse_pairs('=1'))
print('expr ->', parse_pairs('expr=x=1'))
print('blank key ->', end='')
try:
    parse_pairs('  = 2')
except ParseError as e:
    print(' ->', repr(str(e)))
else:
    print(parse_pairs('  = 2'))
print('empty value ->', parse_pairs('key='))
print('last wins ->', parse_pairs('a=1;a=2'))
print('sep ->', parse_pairs('a=1,b=2', sep=','))
print('empty ->', parse_pairs(''))
"

